import { getAllPosts, countPosts, getAllCategories, getSettings, getActiveAdsByPlacement } from "../../../../chunks/database.js";
import { c as sanitizeAds } from "../../../../chunks/sanitize.js";
const load = async ({ params, url }) => {
  const categorySlug = params.slug;
  const page = Number(url.searchParams.get("page")) || 1;
  const limit = 7;
  const posts = await getAllPosts({ page, limit, categorySlug });
  const totalPosts = await countPosts({ categorySlug });
  const totalPages = Math.ceil(totalPosts / limit);
  const categories = await getAllCategories();
  const currentCategory = categories.find((c) => c.slug === categorySlug);
  const popularPosts = await getAllPosts({ limit: 4 });
  const settings = await getSettings();
  const sidebarAds = sanitizeAds(await getActiveAdsByPlacement("sidebar"));
  return {
    posts,
    currentPage: page,
    totalPages,
    categorySlug,
    currentCategory,
    categories,
    popularPosts,
    settings,
    sidebarAds
  };
};
export {
  load
};
